package com.beyondsignal.game.event;
import java.util.*;
public final class ExplorationEventLog{ private final List<ExplorationEvent> events=new ArrayList<>(); public synchronized void append(ExplorationEvent e){events.add(Objects.requireNonNull(e));} public synchronized List<ExplorationEvent> events(){return List.copyOf(events);} public synchronized List<ExplorationEvent> pendingEvents(){return events.stream().filter(e->e.status()==ExplorationEventStatus.PENDING).toList();} public synchronized Optional<ExplorationEvent> eventById(String id){return events.stream().filter(e->e.id().equals(id)).findFirst();} public synchronized void replace(ExplorationEvent e){for(int i=0;i<events.size();i++) if(events.get(i).id().equals(e.id())){events.set(i,e);return;} throw new IllegalArgumentException("Unknown event: "+e.id());}}
